using System;using System.IO;using System.Reflection;using UnityEngine;
namespace FashionFit {
 public sealed class PoseBalancePlayerVerification:MonoBehaviour {
  [Serializable]sealed class Result{public string status="passed",scope="Windows player; real near-picking and button ray path; manual fixed simulation, injected Touch; no physical headset";public int checks,exceptions;public bool modeButton,poseGrip,poseMoved,twoPoseHands,poseRetainedOnEntry,hatPickup,secondRelease,gravity,rigidTranslationInvariant,balancedPull,materialContrast,recovery;public float poseMoveM,translationShapeError,cottonSpanM,stretchSpanM,cottonClothM,stretchClothM,clothRecoveredM,pairForceN;}
  static string requestedOutput;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var args=Environment.GetCommandLineArgs();for(int i=0;i<args.Length-1;i++)if(args[i]=="-fashionPoseBalanceVerify"){requestedOutput=args[i+1];new GameObject("Explicit pose balance player QA").AddComponent<PoseBalancePlayerVerification>();break;}}
  System.Collections.IEnumerator Start(){Application.runInBackground=true;double deadline=Time.realtimeSinceStartupAsDouble+40;while(!FindObjectOfType<FashionFitApp>()||!FindObjectOfType<FashionFitApp>().Ready){if(Time.realtimeSinceStartupAsDouble>deadline){Application.Quit(1);yield break;}yield return null;}RunBatch();}
  static FashionFitApp app;static RunwayVRHands hands;static Result result;static string output;
  static void Check(bool ok,string label){result.checks++;if(!ok)throw new Exception(label);}static void Log(string a,string b,LogType t){if(t==LogType.Error||t==LogType.Exception)result.exceptions++;}
  public static void RunBatch(){GameObject root=null;var mode=Physics.simulationMode;output=Path.GetFullPath(requestedOutput);Directory.CreateDirectory(output);result=new Result();Application.logMessageReceived+=Log;try{Physics.simulationMode=SimulationMode.Script;app=UnityEngine.Object.FindObjectOfType<FashionFitApp>();app.Player.PrepareForVRTrial();Check(app.Ready,app.FatalError);app.Player.EnsureHands();hands=app.Player.Hands;app.Player.PreviewVRMenu();typeof(RunwayPlayer).GetProperty("InVR").SetValue(app.Player,true);typeof(RunwayPlayer).GetProperty("HeadTracked").SetValue(app.Player,true);app.Player.PreviewVRMenu();var menu=app.Player.VRMenu;Check(menu&&menu.Buttons.Count==14,"Missing direct mode button");var button=menu.Buttons[12];Physics.SyncTransforms();Vector3 origin=button.transform.position-button.transform.forward*.22f;Quaternion look=Quaternion.LookRotation(button.transform.forward,Vector3.up);hands.Step(0,true,origin,look,0,0,1f/60);hands.Step(0,true,origin,look,0,1,1f/60);result.modeButton=app.PoseStudio.HandlesVisible;Check(result.modeButton,"Actual Trigger ray cannot activate POSE mode");typeof(RunwayPlayer).GetMethod("InitializeVRInteractionUI",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(app.Player,null);result.poseRetainedOnEntry=app.PoseStudio.HandlesVisible;Check(result.poseRetainedOnEntry,"Entering VR overwrites selected pose mode");menu=app.Player.VRMenu;menu.Hide();
   var rig=app.PoseStudio.Rigs[0];var left=Find(rig,"LeftHand");var right=Find(rig,"RightHand");Vector3 lp=left.transform.position,rp=right.transform.position,before=left.Bone.position;Grip(0,lp,false);Grip(1,rp,false);result.poseGrip=hands.HeldBy(0)&&hands.HeldBy(0).IsJoint;result.twoPoseHands=result.poseGrip&&hands.HeldBy(1)&&hands.HeldBy(1).IsJoint;Check(result.twoPoseHands,"Actual near input cannot hold two pose joints");for(int i=0;i<90;i++){Tick(0,lp+Vector3.up*.18f,0);Tick(1,rp+Vector3.up*.10f,0);}result.poseMoveM=Vector3.Distance(before,left.Bone.position);result.poseMoved=result.poseMoveM>.05f;Check(result.poseMoved,"Joint accepts grip but mannequin does not move");hands.Release(0,false);Check(hands.HeldBy(1)&&right.IsHeld,"Releasing one joint loses other hand");hands.ReleaseAll(false);app.PoseStudio.ResetPose(0);app.PoseStudio.SetHandles(false);
   app.Showroom.SelectOutfitTarget(1);app.Showroom.WearHat(0);var hat=app.Showroom.Hats[0];Vector3[] points=hat.Elastic.MeshAt(0).vertices;int brim=0;for(int i=1;i<points.Length;i++)if(points[i].z>points[brim].z)brim=i;Vector3 hp=hat.transform.TransformPoint(points[brim]);Grip(0,hp,false);result.hatPickup=hands.HeldBy(0)&&hat.IsHeld&&!hat.IsEquipped;Check(result.hatPickup,"Normal Grip cannot lift a hat off its head");for(int i=0;i<55;i++){Tick(0,hp+Vector3.forward*.6f,0);hat.StepHeld(.02f);Physics.Simulate(.02f);Physics.SyncTransforms();}float y=hat.transform.position.y;hands.ReleaseAll(true);for(int i=0;i<80;i++)Physics.Simulate(.02f);result.gravity=hat.GetComponent<Rigidbody>().useGravity&&y-hat.transform.position.y>.10f;Check(result.gravity,"Hat has no gravity after carrying clear of head");hat.ReturnToDisplay();
   result.cottonSpanM=HatCase(hat,MembraneMaterial.Presets[0],true);result.stretchSpanM=HatCase(hat,MembraneMaterial.Presets[1],false);result.materialContrast=result.stretchSpanM>result.cottonSpanM*1.6f;Check(result.materialContrast,"5/10 cm span presets not distinguishable");
   app.PoseStudio.Wear(0,5);var wear=app.PoseStudio.Wearables[0];result.cottonClothM=ClothCase(wear,MembraneMaterial.Presets[0],true);result.stretchClothM=ClothCase(wear,MembraneMaterial.Presets[1],false);Check(result.cottonClothM>.025f&&result.cottonClothM<.060f,"Cotton patch travel is not around the requested 5 cm cap");Check(result.stretchClothM>result.cottonClothM*1.45f&&result.stretchClothM<.115f,"Stretch patch travel is not around the requested 10 cm cap");
   Check(result.exceptions==0,"Unity errors in balance test");Save();typeof(RunwayPlayer).GetProperty("InVR").SetValue(app.Player,false);root=null;Physics.simulationMode=mode;Application.Quit(0);
  }catch(Exception e){result.status="failed";Save();File.WriteAllText(output+"/failure.txt",e.ToString());Debug.LogException(e);Physics.simulationMode=mode;Application.Quit(1);}finally{Application.logMessageReceived-=Log;if(root){if(app&&app.Player)typeof(RunwayPlayer).GetProperty("InVR").SetValue(app.Player,false);UnityEngine.Object.DestroyImmediate(root);}Physics.simulationMode=mode;}}
  static RunwayPoseHandle Find(RunwayPoseRig rig,string bone){foreach(var h in rig.Handles)if(h.Bone.name==bone)return h;throw new Exception(bone);}
  static void Grip(int side,Vector3 p,bool modifier){Physics.SyncTransforms();hands.Step(side,true,p,Quaternion.identity,0,modifier?1:0,1f/60);hands.Step(side,true,p,Quaternion.identity,1,modifier?1:0,1f/60);}
  static void Tick(int side,Vector3 p,float t){hands.Step(side,true,p,Quaternion.identity,1,t,1f/60);}
  static void Sim(RunwayPickup h){h.StepHeld(.02f);Physics.Simulate(.02f);Physics.SyncTransforms();h.Elastic.Step(.02f);}
  static float HatCase(RunwayPickup hat,MembraneMaterial material,bool checkTranslation){hat.ReturnToDisplay();hat.transform.position=new Vector3(0,1.8f,1.2f);hat.GetComponent<Rigidbody>().position=hat.transform.position;hat.Elastic.SetMaterial(material);hat.Elastic.ResetShape();var before=hat.Elastic.MeshAt(0).vertices;int l=0,r=0;for(int i=1;i<before.Length;i++){if(before[i].x<before[l].x)l=i;if(before[i].x>before[r].x)r=i;}Vector3 a=hat.transform.TransformPoint(before[l]),b=hat.transform.TransformPoint(before[r]);Grip(0,a,false);Grip(1,b,false);Check(hands.HeldCount==2&&hat.Elastic.GrabCount==2,"Second hand failed to join carried hat");Vector3 translation=new Vector3(0,.06f,.08f);for(int i=0;i<45;i++){Tick(0,a+translation,0);Tick(1,b+translation,0);Sim(hat);}float error=0;var translated=hat.Elastic.MeshAt(0).vertices;for(int i=0;i<before.Length;i++)error=Mathf.Max(error,(translated[i]-before[i]).magnitude);if(checkTranslation){result.translationShapeError=error;result.rigidTranslationInvariant=error<.002f;Check(result.rigidTranslationInvariant,"Moving both hands together incorrectly stretches the hat");}
   float span0=Vector3.Distance(before[l],before[r]);for(int i=0;i<80;i++){Tick(0,a+translation-Vector3.right*.15f,0);Tick(1,b+translation+Vector3.right*.15f,0);Sim(hat);}var after=hat.Elastic.MeshAt(0).vertices;float extension=Vector3.Distance(after[l],after[r])-span0;Check(extension>material.pullTravelM*.70f&&extension<material.pullTravelM*1.15f,"Hat span exceeded or failed material travel limit");result.pairForceN=hat.Elastic.HandForce0.magnitude;result.balancedPull=(hat.Elastic.HandForce0+hat.Elastic.HandForce1).magnitude<1e-5f;Check(result.balancedPull&&result.pairForceN>1,"Two-hand stretch is not an opposite force pair");for(int i=0;i<95;i++){Tick(0,a+translation+Vector3.right*.15f,0);Tick(1,b+translation-Vector3.right*.15f,0);Sim(hat);}var compressed=hat.Elastic.MeshAt(0).vertices;float compression=span0-Vector3.Distance(compressed[l],compressed[r]);Check(compression>material.pullTravelM*.7f&&compression<material.pullTravelM*1.15f,"Compression span does not respect material travel");Check((hat.Elastic.HandForce0+hat.Elastic.HandForce1).magnitude<1e-5f,"Compression commands are not opposite");hands.Release(0,false);result.secondRelease=hat.IsHeld&&hands.HeldBy(1);Check(result.secondRelease,"First release drops the remaining hat hand");hands.ReleaseAll(true);hat.ReturnToDisplay();return extension;}
  static float ClothCase(PoseWearable wear,MembraneMaterial material,bool recovery){var surface=wear.Surface;surface.SetMaterial(material);surface.ResetShape();wear.Step(1f/60);var baseline=surface.MeshAt(0).vertices;int best=0;float distance=float.PositiveInfinity;for(int i=0;i<baseline.Length;i++){float d=(baseline[i]-new Vector3(-.10f,1.27f,.17f)).sqrMagnitude;if(d<distance){distance=d;best=i;}}Vector3 p=surface.transform.TransformPoint(baseline[best]);Grip(0,p,false);Check(hands.HeldBy(0)&&hands.HeldBy(0).Elastic==surface,"Fabric mode still selects a joint or base");for(int i=0;i<100;i++){Tick(0,p+Vector3.forward*.30f,0);wear.Step(1f/60);}float travel=(surface.MeshAt(0).vertices[best]-baseline[best]).magnitude;hands.ReleaseAll(false);for(int i=0;i<360;i++)wear.Step(1f/60);if(recovery){result.clothRecoveredM=Vector3.Distance(surface.MeshAt(0).vertices[best],baseline[best]);result.recovery=result.clothRecoveredM<travel*.25f;Check(result.recovery,"Cloth does not recover against its body/seam support");}return travel;}
  static void Save(){File.WriteAllText(output+"/verification.json",JsonUtility.ToJson(result,true));Debug.Log("POSE_BALANCE_OK "+JsonUtility.ToJson(result));}
 }
}
